from collections import deque

def components(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); cells=[]
                while q:
                    x,y=q.pop(); cells.append((x,y))
                    for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                        if 0<=nx<h and 0<=ny<w and grid[nx][ny]==col and (nx,ny) not in seen:
                            seen.add((nx,ny)); q.append((nx,ny))
                out.append((col,cells))
    return out

def canon(cells, flip=False):
    mr=min(x for x,y in cells); mc=min(y for x,y in cells)
    pts={(x-mr,y-mc) for x,y in cells}
    if flip:
        w=max(y for x,y in pts)
        pts={(x,w-y) for x,y in pts}
    return frozenset(pts)

def transform(grid):
    comps=components(grid)
    ones=[(i,cells) for i,(col,cells) in enumerate(comps) if col==1]
    for i,cells in ones:
        shape=canon(cells)
        matches=[]
        for j,(col,other) in enumerate(comps):
            if col!=1 and (canon(other)==shape or canon(other,True)==shape):
                matches.append((j,col))
        if matches:
            # prefer direct orientation; otherwise reflected match
            direct=[col for j,col in matches if canon(comps[j][1])==shape]
            target=direct[0] if direct else matches[0][1]
            for r,c in cells: grid[r][c]=target
    return grid

