program='''from collections import deque

def transform(grid):
    grid = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            objects.append((color, cells))

    def shape(cells, reflect=False):
        min_r = min(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        points = {(r - min_r, c - min_c) for r, c in cells}
        if reflect:
            max_c = max(c for _, c in points)
            points = {(r, max_c - c) for r, c in points}
        return frozenset(points)

    for color, cells in objects:
        if color != 1:
            continue
        wanted = shape(cells)
        matches = []
        for other_color, other_cells in objects:
            if other_color == 1:
                continue
            if shape(other_cells) == wanted or shape(other_cells, reflect=True) == wanted:
                matches.append((other_color, shape(other_cells) == wanted))
        if matches:
            target = next((c for c, direct in matches if direct), matches[0][0])
            for r, c in cells:
                grid[r][c] = target
    return grid
'''
